const modules=[['inicio','Panel general',LayoutDashboard],['nuevo','Nuevo documento',FilePlus2],['documentos','Historial',Files],['clientes','Clientes',Users],['productos','Productos',Package],['monedas','Monedas',Coins],['cai','Control CAI',ShieldCheck],['empresa','Mi empresa',Building2],['usuarios','Accesos y roles',UserCog]];
const baseModule=m=>m==='nuevo'?'documentos':m;
const emptyItem=()=>({descripcion:'',cantidad:1,precio:0,producto_id:'',guardar_producto:false,codigo:''});
const emptyDoc=()=>({tipo:'proforma',cliente_id:'',cliente_nombre:'',cliente_rtn:'',cliente_direccion:'',cliente_correo:'',cliente_telefono:'',guardar_cliente:false,moneda_codigo:'HNL',descuento:0,impuesto_pct:15,observaciones:'',orden_compra_exenta:'',constancia_registro_exonerado:'',registro_sag:'',importe_exonerado:0,importe_exento:0,gravado_15:'',gravado_18:'',items:[emptyItem()]});
const money=(v,c='HNL')=>new Intl.NumberFormat('es-HN',{style:'currency',currency:c,minimumFractionDigits:2}).format(Number(v)||0);
const date=v=>v?new Date(v).toLocaleDateString('es-HN',{day:'2-digit',month:'short',year:'numeric'}):'—';
const errText=e=>e?.message||String(e||'Ocurrió un error');
const fmtNum=n=>Number(n||0).toFixed(2);
const labelTipo=t=>({factura:'Factura',proforma:'Proforma',cotizacion:'Cotización'}[t]||t);
const num=v=>Number(v||0);
const cls=s=>String(s||'').replace(/[^a-zA-Z0-9_-]/g,'');


// Convierte el total monetario a palabras en español, incluyendo centavos.
// Es una representación de lectura; no modifica los cálculos ni los importes guardados.
function enteroEnLetras(numero, apocopar = false) {
 const unidades=['','UNO','DOS','TRES','CUATRO','CINCO','SEIS','SIETE','OCHO','NUEVE'];
 const especiales=['DIEZ','ONCE','DOCE','TRECE','CATORCE','QUINCE','DIECISÉIS','DIECISIETE','DIECIOCHO','DIECINUEVE'];
 const decenas=['','','VEINTE','TREINTA','CUARENTA','CINCUENTA','SESENTA','SETENTA','OCHENTA','NOVENTA'];
 const centenas=['','CIENTO','DOSCIENTOS','TRESCIENTOS','CUATROCIENTOS','QUINIENTOS','SEISCIENTOS','SETECIENTOS','OCHOCIENTOS','NOVECIENTOS'];
 function hastaCien(n, apocope) {
  if(n < 10) return n===1&&apocope?'UN':unidades[n];
  if(n < 20) return especiales[n-10];
  if(n < 30) {
   if(n===20)return 'VEINTE';
   const ultimos=['','VEINTIUNO','VEINTIDÓS','VEINTITRÉS','VEINTICUATRO','VEINTICINCO','VEINTISÉIS','VEINTISIETE','VEINTIOCHO','VEINTINUEVE'];
   return n===21&&apocope?'VEINTIÚN':ultimos[n-20];
  }
  const d=Math.floor(n/10),u=n%10;
  return decenas[d]+(u?' Y '+(u===1&&apocope?'UN':unidades[u]):'');
 }
 function hastaMil(n, apocope) {
  if(n===100)return 'CIEN';
  const c=Math.floor(n/100),r=n%100;
  return [c?centenas[c]:'',r?hastaCien(r,apocope):''].filter(Boolean).join(' ');
 }
 if(numero===0)return 'CERO';
 const partes=[];
 const milesMillones=Math.floor(numero/1000000000);
 const millones=Math.floor(numero/1000000)%1000;
 const miles=Math.floor(numero/1000)%1000;
 const unidadesFinales=numero%1000;
 if(milesMillones)partes.push(milesMillones===1?'MIL MILLONES':`${hastaMil(milesMillones,true)} MIL MILLONES`);
 if(millones)partes.push(millones===1?'UN MILLÓN':`${hastaMil(millones,true)} MILLONES`);
 if(miles)partes.push(miles===1?'MIL':`${hastaMil(miles,true)} MIL`);
 if(unidadesFinales)partes.push(hastaMil(unidadesFinales,apocopar));
 return partes.join(' ');
}

function totalEnLetras(valor, codigoMoneda='HNL') {
 const importe=Number(valor);
 if(!Number.isFinite(importe)||importe<0||importe>=1e12)return 'IMPORTE FUERA DE RANGO';
 // Redondea a dos decimales, como el total mostrado en el documento.
 const centavosTotales=Math.round((importe+Number.EPSILON)*100);
 const entero=Math.floor(centavosTotales/100);
 const centavos=centavosTotales%100;
 const usd=String(codigoMoneda).toUpperCase()==='USD';
 const divisa=usd?(entero===1?'DÓLAR':'DÓLARES'):(entero===1?'LEMPIRA':'LEMPIRAS');
 const letras=enteroEnLetras(entero,true);
 const deMillones=entero>=1000000&&entero%1000000===0?' DE':'';
 return `${letras}${deMillones} ${divisa}${centavos?` CON ${enteroEnLetras(centavos,true)} ${centavos===1?'CENTAVO':'CENTAVOS'}`:' EXACTOS'}`;
}

function App(){
 const [session,setSession]=useState(null),[loading,setLoading]=useState(true),[profile,setProfile]=useState(null),[perms,setPerms]=useState([]);
 const [tab,setTab]=useState('inicio'),[mobile,setMobile]=useState(false),[dark,setDark]=useState(false),[toast,setToast]=useState('');
 const [empresa,setEmpresa]=useState(null),[monedas,setMonedas]=useState([]),[clientes,setClientes]=useState([]),[productos,setProductos]=useState([]),[cais,setCais]=useState([]),[docs,setDocs]=useState([]);
 const [editing,setEditing]=useState(null),[preview,setPreview]=useState(null);
 const can=m=>profile?.rol==='administrador'||perms.some(p=>p.rol===profile?.rol&&p.modulo===baseModule(m)&&p.permitido);
 const notify=(message)=>setToast(message);
 useEffect(()=>{if(!supabase){setLoading(false);return}supabase.auth.getSession().then(({data})=>{setSession(data.session);setLoading(false)});const {data:{subscription}}=supabase.auth.onAuthStateChange((_event,s)=>setSession(s));return()=>subscription.unsubscribe()},[]);
 useEffect(()=>{if(!session){setProfile(null);return}let cancelled=false;async function init(){setLoading(true);const {data:p,error}=await supabase.from('perfiles').select('*').eq('id',session.user.id).maybeSingle();if(!cancelled){if(error)notify(errText(error));setProfile(p||null);setLoading(false)}}init();return()=>{cancelled=true}},[session?.user?.id]);
 const reload=async()=>{if(!session||!profile?.activo)return;let tasks=[['permisos',setPerms],['empresa',setEmpresa],['monedas',setMonedas],['clientes',setClientes],['productos',setProductos],['autorizaciones_cai',setCais],['documentos',setDocs]];await Promise.all(tasks.map(async([table,update])=>{const {data,error}=await supabase.from(table).select('*').order(table==='documentos'?'fecha':table==='autorizaciones_cai'||table==='clientes'||table==='productos'?'creado_en':table==='monedas'?'codigo':table==='permisos'?'rol':'id',{ascending:false});if(error){if(!['42501'].includes(error.code))console.warn(table,error.message)}else update(table==='empresa'?data?.[0]||null:data||[])}))};
 useEffect(()=>{if(profile?.activo)reload()},[profile?.id,profile?.activo]);
 function navigate(t){setTab(t);setMobile(false);setEditing(null)}
 async function convertirProforma(d){
  if(d.tipo!=='proforma'||d.estado!=='borrador')return notify('Solo pueden convertirse proformas en borrador');
  if(!window.confirm(`¿Emitir una FACTURA ORIGINAL a partir de ${d.numero}? Se asignará el siguiente número fiscal disponible. Esta acción no se puede deshacer.`))return;
  const {data,error}=await supabase.rpc('convertir_proforma_factura',{p_proforma_id:d.id});
  if(error){notify(errText(error));return}
  notify('Factura original emitida correctamente');
  await reload();
  const {data:factura,error:lectura}=await supabase.from('documentos').select('*').eq('id',data).single();
  if(lectura)return notify(errText(lectura));
  if(factura)await openDoc(factura);
}
 async function convertirCotizacion(d,destino){
  if(d.tipo!=='cotizacion'||d.estado!=='borrador')return notify('Solo pueden convertirse cotizaciones pendientes');
  if(!window.confirm(`¿Convertir ${d.numero} a ${destino==='factura'?'FACTURA ORIGINAL':'PROFORMA'}? Se guardará el documento original.`))return;
  const {data,error}=await supabase.rpc('convertir_cotizacion',{p_cotizacion_id:d.id,p_destino:destino});
  if(error){notify(errText(error));return;}
  notify('Documento convertido correctamente');await reload();
  const {data:dest,error:er}=await supabase.from('documentos').select('*').eq('id',data).single();
  if(er)return notify(errText(er));if(dest)await openDoc(dest);
 }
 async function openDoc(d){const {data,error}=await supabase.from('documento_items').select('*').eq('documento_id',d.id).order('orden');if(error){notify(errText(error));return}setPreview({...d,items:data||[]})}
 async function editDoc(d){if(!['proforma','cotizacion'].includes(d.tipo)||d.estado!=='borrador'){notify('Solo se pueden editar proformas o cotizaciones pendientes');return}const {data,error}=await supabase.from('documento_items').select('*').eq('documento_id',d.id).order('orden');if(error)return notify(errText(error));setEditing({...d,items:(data||[]).map(x=>({...x,guardar_producto:false}))});setTab('nuevo')}
 if(!configured)return <div className="setup"><img className="brand-logo" src={`${import.meta.env.BASE_URL}logo-innovanet.png`} alt="INNOVANET"/><h1>INNOVANET</h1><h3>Conectemos el sistema con Supabase</h3><p>Crea el archivo <code>.env</code> copiando <code>.env.example</code> y agrega la URL y clave pública de tu proyecto Supabase. Ejecuta el archivo SQL antes de iniciar sesión.</p><p className="muted">Nunca coloques la clave service_role en React.</p></div>;
 if(loading)return <div className="splash"><img className="brand-logo" src={`${import.meta.env.BASE_URL}logo-innovanet.png`} alt="INNOVANET"/><h2>Preparando INNOVANET…</h2></div>;
 if(!session)return <Login notify={notify}/>;
 if(!profile)return <div className="setup"><h2>Perfil no disponible</h2><p>Comprueba que ejecutaste el archivo SQL y que existe el disparador de perfiles. Luego cierra sesión e ingresa otra vez.</p><button onClick={()=>supabase.auth.signOut()}>Salir</button></div>;
 if(!profile.activo)return <div className="setup"><LockKeyhole size={40}/><h2>Acceso desactivado</h2><p>Solicita al administrador que reactive tu cuenta.</p><button onClick={()=>supabase.auth.signOut()}>Cerrar sesión</button></div>;
 return <div className={'shell '+(dark?'dark':'')}>
  <aside className={'sidebar '+(mobile?'shown':'')}>
   <div className="brand"><img className="brand-logo" src={`${import.meta.env.BASE_URL}logo-innovanet.png`} alt="INNOVANET"/><div><strong>INNOVANET</strong><small>Gestión comercial</small></div><button className="icon-button mobile-close" onClick={()=>setMobile(false)}><X size={20}/></button></div>
   <p className="side-label">ESPACIO DE TRABAJO</p><nav>{modules.filter(([id])=>can(id)).map(([id,label,I])=><button key={id} className={'nav-link '+(tab===id?'active':'')} onClick={()=>navigate(id)}><I size={18}/><span>{label}</span>{tab===id&&<ChevronRight size={15}/>}</button>)}</nav>
   <div className="side-bottom"><div className="avatar">{(profile.nombre||'U')[0].toUpperCase()}</div><div className="side-user"><b>{profile.nombre}</b><small>{profile.rol}</small></div><button title="Cerrar sesión" className="icon-button" onClick={()=>supabase.auth.signOut()}><LogOut size={18}/></button></div>
  </aside>
  {mobile&&<div className="overlay" onClick={()=>setMobile(false)}/>}
  <main className="main"><header className="topbar"><div className="row gap"><button className="icon-button menu-mobile" onClick={()=>setMobile(true)}><Menu/></button><div><div className="breadcrumb">INNOVANET / <b>{modules.find(x=>x[0]===tab)?.[1]}</b></div><h2>{modules.find(x=>x[0]===tab)?.[1]}</h2></div></div><div className="top-actions"><span className="hello">Hola, {profile.nombre?.split(' ')[0]}</span><button className="icon-button" title="Cambiar tema" onClick={()=>setDark(!dark)}>{dark?<Sun size={19}/>:<Moon size={19}/>}</button><button className="icon-button" title="Actualizar datos" onClick={reload}><RefreshCw size={19}/></button></div></header>
   <div className="content">{!can(tab)?<div className="panel">No tienes autorización para este módulo.</div>:<>
    {tab==='inicio'&&<Dashboard docs={docs} moneda="HNL" openDoc={openDoc} navigate={navigate} empresa={empresa} can={can}/>}
    {tab==='nuevo'&&<NewDocument key={editing?.id||'nuevo'} initial={editing} clientes={clientes} productos={productos} monedas={monedas} empresa={empresa} onSaved={async(id)=>{await reload();const {data}=await supabase.from('documentos').select('*').eq('id',id).single();if(data)await openDoc(data);setEditing(null);setTab('documentos')}} notify={notify}/>}
    {tab==='documentos'&&<Documents docs={docs} onPreview={openDoc} onEdit={editDoc} onConvert={convertirProforma} onConvertQuote={convertirCotizacion} onNew={()=>navigate('nuevo')} notify={notify} isAdmin={profile.rol==='administrador'} reload={reload}/>}
    {tab==='clientes'&&<Crud title="Clientes" rows={clientes} table="clientes" fields={[['nombre','Nombre o razón social',true],['rtn','RTN'],['telefono','Teléfono'],['correo','Correo electrónico'],['direccion','Dirección']]} notify={notify} reload={reload}/>}
    {tab==='productos'&&<Crud title="Productos y servicios" rows={productos} table="productos" fields={[['codigo','Código'],['nombre','Nombre del producto / servicio',true],['descripcion','Descripción'],['precio','Precio',true,'number']]} notify={notify} reload={reload}/>}
    {tab==='monedas'&&<Crud title="Monedas y tipos de cambio" rows={monedas} table="monedas" fields={[['codigo','Código ISO (HNL / USD)',true],['nombre','Nombre',true],['simbolo','Símbolo',true],['tasa_hnl','Lempiras por unidad',true,'number']]} notify={notify} reload={reload} primaryKey="codigo" extra="La tasa USD se actualiza manualmente. Se almacena la tasa de cada documento al emitirlo; no cambia facturas anteriores."/>}
    {tab==='cai'&&<CAI rows={cais} reload={reload} notify={notify}/>}
    {tab==='empresa'&&<Empresa info={empresa} reload={reload} notify={notify}/>}
    {tab==='usuarios'&&<UsersAdmin usersCurrent={profile} perms={perms} reload={reload} notify={notify}/>}
   </>}</div>
  </main>
  {preview&&<Preview doc={preview} onClose={()=>setPreview(null)} onEdit={()=>{const d=preview;setPreview(null);editDoc(d)}} onConvert={()=>{const d=preview;setPreview(null);convertirProforma(d)}} onConvertQuote={(destino)=>{const d=preview;setPreview(null);convertirCotizacion(d,destino)}} facturaVinculada={docs.find(x=>x.origen_proforma_id===preview.id)} cotizacionVinculada={docs.find(x=>x.origen_cotizacion_id===preview.id)} onOpenRelated={openDoc} empresa={empresa} autorizaciones={cais}/>}
  {toast&&<div className="toast" role="alert">{toast}<button onClick={()=>setToast('')}><X size={15}/></button></div>}
 </div>
}
function Login({notify}){const [email,setEmail]=useState(''),[password,setPassword]=useState(''),[name,setName]=useState(''),[showSignup,setSignup]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState('');async function submit(e){e.preventDefault();setBusy(true);setError('');const result=showSignup?await supabase.auth.signUp({email,password,options:{data:{nombre:name}}}):await supabase.auth.signInWithPassword({email,password});setBusy(false);if(result.error)setError(result.error.message);else if(showSignup)notify('Cuenta creada. Revisa tu correo para confirmar el acceso si está habilitada la confirmación. El administrador deberá asignarte permisos.')}return <div className="login-bg"><div className="login-art"><div className="login-label">PLATAFORMA DE GESTIÓN</div><h1>Tu negocio,<br/><em>más organizado.</em></h1><p>Facturación, cotizaciones y administración de clientes desde un solo lugar.</p><div className="decor-card"><FileText size={25}/><div><b>Documentos inteligentes</b><small>De la cotización a la factura</small></div><CheckCircle2/></div><div className="login-footer">INNOVANET · Tecnología para crecer</div></div><div className="login-form-col"><form className="login-card" onSubmit={submit}><img className="brand-logo" src={`${import.meta.env.BASE_URL}logo-innovanet.png`} alt="INNOVANET"/><h2>{showSignup?'Solicitar cuenta':'Bienvenido de nuevo'}</h2><p>Ingresa tus credenciales para continuar.</p>{showSignup&&<label>Nombre completo<input required value={name} onChange={e=>setName(e.target.value)} placeholder="Tu nombre"/></label>}<label>Correo electrónico<input type="email" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="correo@empresa.com"/></label><label>Contraseña<input type="password" minLength={6} required value={password} onChange={e=>setPassword(e.target.value)} placeholder="••••••••"/></label>{error&&<p className="error">{error}</p>}<button className="btn primary full" disabled={busy}>{busy?'Procesando…':showSignup?'Crear cuenta':'Iniciar sesión'} <ChevronRight size={17}/></button><button type="button" className="text-button" onClick={()=>{setSignup(!showSignup);setError('')}}>{showSignup?'Ya tengo cuenta · Iniciar sesión':'¿No tienes cuenta? Solicita acceso'}</button><small className="hint">Las cuentas nuevas no reciben privilegios administrativos.</small></form></div></div>}
function Dashboard({docs,navigate,openDoc,empresa,can}){const fact=docs.filter(x=>x.tipo==='factura'&&x.estado==='emitida'),pro=docs.filter(x=>x.tipo==='proforma');const now=new Date(),month=fact.filter(d=>{const f=new Date(d.fecha);return f.getMonth()===now.getMonth()&&f.getFullYear()===now.getFullYear()});return <><div className="hero"><div><span className="eyebrow">TU ESPACIO COMERCIAL</span><h1>Bienvenido a {empresa?.nombre||'INNOVANET'}</h1><p>Consulta tus resultados, prepara documentos y mantén tu operación organizada.</p></div>{can('nuevo')&&<button className="btn white" onClick={()=>navigate('nuevo')}><Plus size={19}/> Nuevo documento</button>}</div><div className="stats"><Stat label="Facturas emitidas" value={fact.length} icon={Files}/><Stat label="Proformas" value={pro.length} icon={FileText}/><Stat label="Total facturado este mes (HNL)" value={money(month.reduce((a,d)=>a+Number(d.total)*Number(d.tasa_hnl),0),'HNL')} icon={Coins}/><Stat label="Documentos del sistema" value={docs.length} icon={LayoutDashboard}/></div><section className="panel"><div className="section-title"><div><h3>Actividad reciente</h3><p>Últimos documentos registrados</p></div><button className="btn ghost" onClick={()=>navigate('documentos')}>Ver historial <ChevronRight size={16}/></button></div><DocumentTable docs={docs.slice(0,6)} onPreview={openDoc}/></section></>}
function Stat({label,value,icon:I}){return <div className="stat"><div className="stat-icon"><I size={21}/></div><small>{label}</small><b>{value}</b></div>}
function Documents({docs,onPreview,onEdit,onConvert,onConvertQuote,onNew,isAdmin,reload,notify}){const [q,setQ]=useState(''),[tipo,setTipo]=useState('todos'),[estado,setEstado]=useState('todos'),[desde,setDesde]=useState(''),[hasta,setHasta]=useState('');const filtered=docs.filter(d=>{const h=new Date(d.fecha).toISOString().slice(0,10);return (tipo==='todos'||d.tipo===tipo)&&(estado==='todos'||d.estado===estado)&&(!desde||h>=desde)&&(!hasta||h<=hasta)&&[d.numero,d.cliente_nombre,d.cliente_rtn].join(' ').toLowerCase().includes(q.toLowerCase())});async function annul(d){if(!window.confirm(`¿Anular factura ${d.numero}? Se conservará en el historial y no se reutilizará el correlativo.`))return;const {error}=await supabase.rpc('anular_factura',{p_id:d.id});if(error)notify(errText(error));else {notify('Factura anulada correctamente');reload()}}return <section className="panel"><div className="section-title"><div><h3>Historial de documentos</h3><p>Consulta, filtra, imprime o edita tus documentos.</p></div><button className="btn primary" onClick={onNew}><Plus size={18}/> Crear documento</button></div><div className="filters"><label className="search"><Search size={17}/><input placeholder="Número, cliente o RTN" value={q} onChange={e=>setQ(e.target.value)}/></label><select value={tipo} onChange={e=>setTipo(e.target.value)}><option value="todos">Todos los tipos</option><option value="proforma">Proformas</option><option value="cotizacion">Cotizaciones</option><option value="factura">Facturas</option></select><select value={estado} onChange={e=>setEstado(e.target.value)}><option value="todos">Todos los estados</option><option value="borrador">Borrador</option><option value="emitida">Emitida</option><option value="anulada">Anulada</option></select><input aria-label="Desde" title="Desde" type="date" value={desde} onChange={e=>setDesde(e.target.value)}/><input aria-label="Hasta" title="Hasta" type="date" value={hasta} onChange={e=>setHasta(e.target.value)}/></div><div className="table-scroll"><table><thead><tr><th>Documento</th><th>Cliente</th><th>Fecha</th><th>Moneda</th><th>Total</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>{filtered.map(d=><tr key={d.id}><td><strong>{d.numero}</strong><small>{labelTipo(d.tipo)}</small></td><td>{d.cliente_nombre}</td><td>{date(d.fecha)}</td><td>{d.moneda_codigo}</td><td className="amount">{money(d.total,d.moneda_codigo)}</td><td><span className={'pill '+cls(d.estado)}>{d.estado}</span></td><td><div className="table-actions"><button title="Ver e imprimir" onClick={()=>onPreview(d)}><Eye size={16}/></button>{d.tipo==='cotizacion'&&d.estado==='borrador'&&!docs.some(x=>x.origen_cotizacion_id===d.id)&&<><button title="Convertir cotización a proforma" onClick={()=>onConvertQuote(d,'proforma')}>A proforma</button><button title="Convertir cotización a factura" onClick={()=>onConvertQuote(d,'factura')}>A factura</button></>}{d.tipo==='proforma'&&d.estado==='borrador'&&!docs.some(x=>x.origen_proforma_id===d.id)&&<button title="Convertir en factura original" onClick={()=>onConvert(d)}><FileCheck2 size={16}/></button>}{d.tipo==='proforma'&&docs.some(x=>x.origen_proforma_id===d.id)&&<button title="Ver factura vinculada" onClick={()=>onPreview(docs.find(x=>x.origen_proforma_id===d.id))}><FileCheck2 size={16}/></button>}{(d.tipo==='proforma'||d.tipo==='cotizacion')&&d.estado==='borrador'&&!docs.some(x=>x.origen_proforma_id===d.id||x.origen_cotizacion_id===d.id)&&<button title="Editar" onClick={()=>onEdit(d)}><Edit3 size={16}/></button>}{isAdmin&&d.tipo==='factura'&&d.estado==='emitida'&&<button title="Anular factura" onClick={()=>annul(d)}><Trash2 size={16}/></button>}</div></td></tr>)}{!filtered.length&&<tr><td colSpan="7" className="empty">No hay documentos para los filtros seleccionados.</td></tr>}</tbody></table></div><div className="table-foot">{filtered.length} registros · Ordenados del más reciente al más antiguo</div></section>}
function DocumentTable({docs,onPreview}){return <div className="table-scroll"><table><thead><tr><th>Número</th><th>Cliente</th><th>Fecha</th><th>Tipo</th><th>Total</th><th></th></tr></thead><tbody>{docs.map(d=><tr key={d.id}><td><b>{d.numero}</b></td><td>{d.cliente_nombre}</td><td>{date(d.fecha)}</td><td>{d.tipo}</td><td className="amount">{money(d.total,d.moneda_codigo)}</td><td><button className="action-link" onClick={()=>onPreview(d)}>Ver <Eye size={15}/></button></td></tr>)}{!docs.length&&<tr><td className="empty" colSpan="6">Aún no tienes documentos.</td></tr>}</tbody></table></div>}
function NewDocument({initial,clientes,productos,monedas,empresa,onSaved,notify}){const [d,setD]=useState(()=>initial?{...emptyDoc(),...initial,guardar_cliente:false,cliente_correo:'',cliente_telefono:''}: {...emptyDoc(),impuesto_pct:empresa?.impuesto_pct??15});const [busy,setBusy]=useState(false);const set=(k,v)=>setD(prev=>({...prev,[k]:v}));const setItem=(i,k,v)=>setD(prev=>({...prev,items:prev.items.map((item,j)=>i===j?{...item,[k]:v}:item)}));const sub=d.items.reduce((a,x)=>a+Math.round((Number(x.cantidad)||0)*(Number(x.precio)||0)*100)/100,0);const base=Math.max(0,sub-(Number(d.descuento)||0));const imp=Math.round(base*(Number(d.impuesto_pct)||0))/100;const total=base+imp;const selectedMoneda=monedas.find(x=>x.codigo===d.moneda_codigo);async function save(e){e.preventDefault();if(d.items.some(x=>!x.descripcion.trim()||Number(x.cantidad)<=0||Number(x.precio)<0))return notify('Revisa descripciones, cantidades y precios');setBusy(true);const {data,error}=await supabase.rpc('guardar_documento',{p_datos:{tipo:d.tipo,cliente_id:d.cliente_id||null,cliente_nombre:d.cliente_nombre,cliente_rtn:d.cliente_rtn||'',cliente_direccion:d.cliente_direccion||'',cliente_correo:d.cliente_correo||'',cliente_telefono:d.cliente_telefono||'',guardar_cliente:!!d.guardar_cliente,moneda_codigo:d.moneda_codigo,descuento:Number(d.descuento)||0,impuesto_pct:Number(d.impuesto_pct),observaciones:d.observaciones||'',orden_compra_exenta:d.orden_compra_exenta||'',constancia_registro_exonerado:d.constancia_registro_exonerado||'',registro_sag:d.registro_sag||'',importe_exonerado:num(d.importe_exonerado),importe_exento:num(d.importe_exento),gravado_15:d.gravado_15===''?null:num(d.gravado_15),gravado_18:d.gravado_18===''?null:num(d.gravado_18)},p_items:d.items.map(x=>({producto_id:x.producto_id||null,descripcion:x.descripcion,cantidad:Number(x.cantidad),precio:Number(x.precio),guardar_producto:!!x.guardar_producto,codigo:x.codigo||''})),p_id:initial?.id||null});setBusy(false);if(error)notify(errText(error));else{notify(d.tipo==='factura'?'Factura emitida; lista para imprimir':'Proforma guardada; lista para imprimir');onSaved(data)}}return <form onSubmit={save}><div className="document-layout"><div className="document-main"><section className="panel"><div className="section-title"><div><h3>{initial?'Editar '+labelTipo(initial.tipo):'Crear nuevo documento'}</h3><p>Completa los datos comerciales y agrega los artículos.</p></div><span className="pill borrador">{initial?.numero||'Nuevo'}</span></div><div className="form-grid"><label>Tipo de documento<select value={d.tipo} disabled={!!initial} onChange={e=>set('tipo',e.target.value)}><option value="proforma">Proforma</option><option value="cotizacion">Cotización comercial</option><option value="factura">Factura fiscal</option></select></label><label>Moneda<select value={d.moneda_codigo} onChange={e=>set('moneda_codigo',e.target.value)} required>{monedas.filter(x=>x.activa).map(x=><option key={x.codigo} value={x.codigo}>{x.nombre} ({x.codigo})</option>)}</select></label></div>{d.tipo==='factura'&&<div className="notice"><AlertTriangle size={18}/> Al guardar, la factura quedará emitida y no podrá modificarse. Verifica primero el CAI y todos los datos.</div>}</section><section className="panel"><div className="section-title"><div><h3>Datos del cliente</h3><p>Selecciona uno existente o escribe uno nuevo.</p></div></div><div className="form-grid"><label className="span2">Cliente existente<select value={d.cliente_id||''} onChange={e=>{const id=e.target.value;const c=clientes.find(x=>x.id===id);setD(p=>({...p,cliente_id:id,cliente_nombre:c?.nombre||'',cliente_rtn:c?.rtn||'',cliente_direccion:c?.direccion||'',guardar_cliente:false}))}}><option value="">— Registrar manualmente —</option>{clientes.filter(c=>c.activo).map(c=><option key={c.id} value={c.id}>{c.nombre}</option>)}</select></label><label>Nombre o razón social *<input value={d.cliente_nombre} required onChange={e=>{set('cliente_nombre',e.target.value)}}/></label><label>RTN<input value={d.cliente_rtn||''} onChange={e=>set('cliente_rtn',e.target.value)}/></label><label className="span2">Dirección<input value={d.cliente_direccion||''} onChange={e=>set('cliente_direccion',e.target.value)}/></label>{!d.cliente_id&&<><label>Teléfono (opcional)<input value={d.cliente_telefono||''} onChange={e=>set('cliente_telefono',e.target.value)}/></label><label>Correo (opcional)<input type="email" value={d.cliente_correo||''} onChange={e=>set('cliente_correo',e.target.value)}/></label><label className="checkline span2"><input type="checkbox" checked={!!d.guardar_cliente} onChange={e=>set('guardar_cliente',e.target.checked)}/> Guardar este cliente en el catálogo al registrar el documento</label></>}</div></section><section className="panel"><div className="section-title"><div><h3>Productos y servicios</h3><p>Puedes agregar artículos sin que existan previamente en el catálogo.</p></div><button type="button" className="btn ghost" onClick={()=>set('items',[...d.items,emptyItem()])}><Plus size={17}/> Agregar línea</button></div><div className="items">{d.items.map((it,i)=><div className="item-card" key={i}><div className="item-top"><b>Artículo {i+1}</b><button type="button" className="icon-button danger" title="Quitar línea" disabled={d.items.length===1} onClick={()=>set('items',d.items.filter((_,j)=>i!==j))}><Trash2 size={16}/></button></div><div className="item-form"><label className="item-product">Elegir catálogo<select value={it.producto_id||''} onChange={e=>{const p=productos.find(x=>x.id===e.target.value);setD(prev=>({...prev,items:prev.items.map((it,j)=>i===j?{...it,producto_id:p?.id||'',descripcion:p?.nombre||'',precio:p?.precio??0,guardar_producto:false}:it)}))}}><option value="">Artículo manual</option>{productos.filter(p=>p.activo).map(p=><option value={p.id} key={p.id}>{p.codigo?`${p.codigo} · `:''}{p.nombre}</option>)}</select></label><label className="item-name">Descripción *<input required value={it.descripcion} onChange={e=>setItem(i,'descripcion',e.target.value)} placeholder="Nombre del producto o servicio"/></label><label>Cantidad<input type="number" step="0.001" min="0.001" required value={it.cantidad} onChange={e=>setItem(i,'cantidad',e.target.value)}/></label><label>Precio<input type="number" step="0.01" min="0" required value={it.precio} onChange={e=>setItem(i,'precio',e.target.value)}/></label><div className="item-total"><small>Importe</small><strong>{money(Number(it.cantidad)*Number(it.precio),d.moneda_codigo)}</strong></div></div>{!it.producto_id&&<label className="checkline"><input type="checkbox" checked={!!it.guardar_producto} onChange={e=>setItem(i,'guardar_producto',e.target.checked)}/> Guardar este artículo en productos</label>}</div>)}</div></section>{d.tipo!=='cotizacion'&&<section className="panel"><div className="section-title"><div><h3>Datos fiscales y exoneraciones</h3><p>Los tres números son opcionales y se imprimirán dentro del margen del documento.</p></div></div><div className="form-grid">
{[['orden_compra_exenta','N° Correlativo de Orden de Compra Exenta'],['constancia_registro_exonerado','N° Correlativo de Constancia de Registro Exonerado'],['registro_sag','N° Identificativo del Registro de la SAG']].map(([k,t])=><label key={k} className="span2">{t}<input maxLength={100} value={d[k]||''} onChange={e=>set(k,e.target.value)} placeholder="Dejar vacío cuando no aplique"/></label>)}
<label>Importe exonerado<input type="number" min="0" step="0.01" value={d.importe_exonerado} onChange={e=>set('importe_exonerado',e.target.value)}/></label>
<label>Importe exento<input type="number" min="0" step="0.01" value={d.importe_exento} onChange={e=>set('importe_exento',e.target.value)}/></label>
<label>Base gravada 15%<input type="number" min="0" step="0.01" value={d.gravado_15} onChange={e=>set('gravado_15',e.target.value)} placeholder="Automático si vacío"/></label>
<label>Base gravada 18%<input type="number" min="0" step="0.01" value={d.gravado_18} onChange={e=>set('gravado_18',e.target.value)} placeholder="Automático si vacío"/></label>
</div><p className="hint">Las bases e impuestos deben cuadrar con subtotal, descuentos y total. La base de datos rechazará importes inconsistentes.</p></section>}
<section className="panel"><label>Observaciones<textarea rows="3" placeholder="Condiciones de venta, vigencia de cotización, anotaciones…" value={d.observaciones||''} onChange={e=>set('observaciones',e.target.value)}/></label></section></div><div className="document-side"><section className="panel summary"><h3>Resumen del documento</h3><div className="summary-line"><span>Subtotal</span><b>{money(sub,d.moneda_codigo)}</b></div><label>Descuento ({d.moneda_codigo})<input type="number" min="0" max={sub} step="0.01" value={d.descuento} onChange={e=>set('descuento',e.target.value)}/></label><label>Impuesto (%)<input type="number" min="0" max="100" step="0.01" value={d.impuesto_pct} onChange={e=>set('impuesto_pct',e.target.value)}/></label><div className="summary-line"><span>Impuesto</span><b>{money(imp,d.moneda_codigo)}</b></div><div className="summary-grand"><span>Total</span><b>{money(total,d.moneda_codigo)}</b></div><p className="hint">Moneda: {selectedMoneda?.nombre||d.moneda_codigo}. Tasa registrada: {selectedMoneda?.tasa_hnl||'—'} HNL por unidad.</p><button disabled={busy} type="submit" className="btn primary full"><Save size={18}/>{busy?'Guardando…':initial?'Guardar cambios':d.tipo==='factura'?'Emitir y abrir factura':'Guardar y abrir proforma'}</button><small className="hint">El documento se abrirá automáticamente para impresión.</small></section></div></div></form>}
function Crud({title,rows,table,fields,primaryKey='id',notify,reload,extra}){const [edit,setEdit]=useState(null),[form,setForm]=useState(null),[search,setSearch]=useState(''),[busy,setBusy]=useState(false);function begin(row){setEdit(row||null);setForm(row?{...row}:Object.fromEntries(fields.map(([k])=>[k,''])))}async function submit(e){e.preventDefault();const payload=Object.fromEntries(fields.map(([k,, ,type])=>[k,type==='number'?Number(form[k]):form[k]]));setBusy(true);const {error}=edit?await supabase.from(table).update(payload).eq(primaryKey,edit[primaryKey]):await supabase.from(table).insert(payload);setBusy(false);if(error)notify(errText(error));else{notify('Registro guardado');setForm(null);await reload()}}return <section className="panel"><div className="section-title"><div><h3>{title}</h3><p>{extra||'Administra los registros para reutilizarlos en los documentos.'}</p></div><button className="btn primary" onClick={()=>begin(null)}><Plus size={18}/> Nuevo registro</button></div><label className="search standalone"><Search size={17}/><input placeholder="Buscar registro..." value={search} onChange={e=>setSearch(e.target.value)}/></label><div className="table-scroll"><table><thead><tr>{fields.slice(0,4).map(([k,label])=><th key={k}>{label}</th>)}<th>Acción</th></tr></thead><tbody>{rows.filter(r=>fields.some(([k])=>String(r[k]??'').toLowerCase().includes(search.toLowerCase()))).map(r=><tr key={r[primaryKey]}>{fields.slice(0,4).map(([k])=><td key={k}>{String(r[k]??'')}</td>)}<td><button className="action-link" onClick={()=>begin(r)}><Edit3 size={15}/> Editar</button></td></tr>)}{!rows.length&&<tr><td colSpan={fields.length+1} className="empty">No existen registros. Crea el primero.</td></tr>}</tbody></table></div>{form&&<div className="modal-backdrop" onClick={()=>setForm(null)}><div className="modal small" onClick={e=>e.stopPropagation()}><div className="modal-title"><h3>{edit?'Editar':'Nuevo'} · {title}</h3><button className="icon-button" onClick={()=>setForm(null)}><X/></button></div><form onSubmit={submit} className="modal-body">{fields.map(([key,label,required,type])=><label key={key}>{label}<input type={type||'text'} step={type==='number'?'any':undefined} required={!!required} disabled={!!edit&&key===primaryKey} value={form[key]??''} onChange={e=>setForm({...form,[key]:e.target.value})}/></label>)}<button disabled={busy} type="submit" className="btn primary full"><Save size={17}/> Guardar registro</button></form></div></div>}</section>}
function CAI({rows,notify,reload}){const [form,setForm]=useState(null),[busy,setBusy]=useState(false);const fields=[['cai','Código CAI'],['establecimiento','Establecimiento (3 dígitos)'],['punto_emision','Punto de emisión (3 dígitos)'],['tipo_documento','Tipo documento (2 dígitos)'],['desde','Rango inicial'],['hasta','Rango final'],['siguiente','Siguiente correlativo'],['fecha_limite','Fecha límite de emisión']];async function save(e){e.preventDefault();const val={...form,desde:Number(form.desde),hasta:Number(form.hasta),siguiente:Number(form.siguiente),activa:false};setBusy(true);const {error}=await supabase.from('autorizaciones_cai').insert(val);setBusy(false);if(error)notify(errText(error));else{setForm(null);notify('Autorización registrada; actívala para emitir facturas');reload()}}async function activate(row){if(!window.confirm('¿Activar este CAI? Se desactivará el anterior.'))return;const {error}=await supabase.rpc('activar_cai',{p_id:row.id});if(error)notify(errText(error));else{notify('CAI activo actualizado');reload()}}return <section className="panel"><div className="section-title"><div><h3>Autorizaciones de facturación</h3><p>Administra CAI, vigencia y rangos autorizados por el SAR.</p></div><button className="btn primary" onClick={()=>setForm({cai:'',establecimiento:'001',punto_emision:'001',tipo_documento:'01',desde:1,hasta:1000,siguiente:1,fecha_limite:''})}><Plus size={18}/> Nueva autorización</button></div><div className="notice"><AlertTriangle size={19}/> Configura únicamente los datos de una autorización real emitida por el SAR. Este sistema no genera ni solicita CAI ante el SAR.</div><div className="table-scroll"><table><thead><tr><th>CAI</th><th>Formato</th><th>Rango</th><th>Siguiente</th><th>Vencimiento</th><th>Estado</th><th></th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td className="code-cell">{r.cai}</td><td>{r.establecimiento}-{r.punto_emision}-{r.tipo_documento}</td><td>{[r.establecimiento,r.punto_emision,r.tipo_documento,String(r.desde).padStart(8,'0')].join('-')} a {[r.establecimiento,r.punto_emision,r.tipo_documento,String(r.hasta).padStart(8,'0')].join('-')}</td><td>{[r.establecimiento,r.punto_emision,r.tipo_documento,String(r.siguiente).padStart(8,'0')].join('-')}</td><td>{r.fecha_limite}</td><td><span className={'pill '+(r.activa?'emitida':'borrador')}>{r.activa?'Activo':'Inactivo'}</span></td><td>{!r.activa&&<button className="action-link" onClick={()=>activate(r)}>Activar</button>}</td></tr>)}{!rows.length&&<tr><td colSpan="7" className="empty">Aún no has configurado un CAI.</td></tr>}</tbody></table></div>{form&&<div className="modal-backdrop" onClick={()=>setForm(null)}><div className="modal small" onClick={e=>e.stopPropagation()}><div className="modal-title"><h3>Nueva autorización CAI</h3><button className="icon-button" onClick={()=>setForm(null)}><X/></button></div><form onSubmit={save} className="modal-body">{fields.map(([k,label])=><label key={k}>{label}<input required type={k==='fecha_limite'?'date': ['desde','hasta','siguiente'].includes(k)?'number':'text'} min={['desde','hasta','siguiente'].includes(k)?1:undefined} pattern={['establecimiento','punto_emision'].includes(k)?'[0-9]{3}':k==='tipo_documento'?'[0-9]{2}':undefined} value={form[k]} onChange={e=>setForm({...form,[k]:e.target.value})}/></label>)}<button disabled={busy} className="btn primary full">Guardar autorización</button></form></div></div>}</section>}
function Empresa({info,notify,reload}){const [form,setForm]=useState(null);useEffect(()=>setForm(info?{...info}:null),[info]);if(!form)return <p>Configura la empresa en Supabase.</p>;const fields=[['nombre','Nombre comercial'],['razon_social','Razón social'],['rtn','RTN'],['direccion','Dirección'],['telefono','Teléfono'],['correo','Correo'],['lema','Lema comercial'],['impuesto_nombre','Nombre del impuesto'],['impuesto_pct','Impuesto predeterminado (%)','number'],['pie_documento','Texto al pie del documento']];async function save(e){e.preventDefault();const {error}=await supabase.from('empresa').update({...Object.fromEntries(fields.map(([k,,type])=>[k,type==='number'?Number(form[k]):form[k]])),actualizado_en:new Date().toISOString()}).eq('id',1);if(error)notify(errText(error));else{notify('Datos de empresa actualizados');reload()}}return <section className="panel"><div className="section-title"><div><h3>Configuración empresarial</h3><p>Datos de la empresa que aparecerán en nuevos documentos.</p></div></div><form onSubmit={save} className="form-grid">{fields.map(([k,label,type])=><label key={k} className={k==='direccion'||k==='pie_documento'?'span2':''}>{label}<input type={type||'text'} step={type==='number'?'0.01':undefined} min={type==='number'?0:undefined} max={type==='number'?100:undefined} value={form[k]??''} onChange={e=>setForm({...form,[k]:e.target.value})}/></label>)}<div className="span2"><button className="btn primary"><Save size={18}/> Guardar cambios</button></div></form></section>}
function UsersAdmin({usersCurrent,perms,notify,reload}){const [users,setUsers]=useState([]);const [busy,setBusy]=useState(false);useEffect(()=>{supabase.from('perfiles').select('*').order('creado_en',{ascending:false}).then(({data})=>setUsers(data||[]))},[perms]);async function changeUser(id,prop,value){if(id===usersCurrent.id&&['rol','activo'].includes(prop))return notify('No puedes cambiar tu propio rol ni desactivar tu cuenta');setBusy(true);const {error}=await supabase.from('perfiles').update({[prop]:value}).eq('id',id);setBusy(false);if(error)notify(errText(error));else{setUsers(p=>p.map(x=>x.id===id?{...x,[prop]:value}:x));notify('Acceso actualizado')}}async function changePerm(rol,modulo,permitido){const {error}=await supabase.from('permisos').update({permitido}).eq('rol',rol).eq('modulo',modulo);if(error)notify(errText(error));else{notify('Permisos actualizados');reload()}}return <><section className="panel"><div className="section-title"><div><h3>Usuarios y accesos</h3><p>Solo el administrador puede asignar roles o habilitar cuentas.</p></div></div><div className="notice"><UserCog size={18}/> Los usuarios crean su cuenta desde el inicio de sesión; el administrador decide qué rol asignar. Las contraseñas nunca se muestran.</div><div className="table-scroll"><table><thead><tr><th>Usuario</th><th>Correo</th><th>Rol</th><th>Acceso</th></tr></thead><tbody>{users.map(u=><tr key={u.id}><td><b>{u.nombre}</b>{u.id===usersCurrent.id&&<small>Tu cuenta</small>}</td><td>{u.correo}</td><td><select disabled={busy||u.id===usersCurrent.id} value={u.rol} onChange={e=>changeUser(u.id,'rol',e.target.value)}><option value="administrador">Administrador</option><option value="operador">Operador</option><option value="consulta">Consulta</option></select></td><td><label className="checkline"><input disabled={busy||u.id===usersCurrent.id} type="checkbox" checked={u.activo} onChange={e=>changeUser(u.id,'activo',e.target.checked)}/> Habilitado</label></td></tr>)}</tbody></table></div></section><section className="panel"><div className="section-title"><div><h3>Permisos por módulo</h3><p>El rol Administrador dispone de todos los módulos. Configura los demás roles.</p></div></div><div className="table-scroll"><table><thead><tr><th>Módulo</th><th>Operador</th><th>Consulta</th></tr></thead><tbody>{modules.filter(([id])=>id!=='nuevo').map(([id,label])=><tr key={id}><td>{label}</td>{['operador','consulta'].map(rol=><td key={rol}><input type="checkbox" checked={!!perms.find(p=>p.rol===rol&&p.modulo===id)?.permitido} onChange={e=>changePerm(rol,id,e.target.checked)}/></td>)}</tr>)}</tbody></table></div></section></>}
function Preview({doc,onClose,onEdit,onConvert,onConvertQuote,facturaVinculada,cotizacionVinculada,onOpenRelated,autorizaciones=[]}){
 const company=doc.empresa_snapshot||{};
 const isFactura=doc.tipo==='factura';const isProforma=doc.tipo==='proforma';const isCotizacion=doc.tipo==='cotizacion';const fiscal=isFactura||isProforma;
 const moneda=doc.moneda_codigo||'HNL';
 const fmt=n=>money(Number(n||0),moneda);
 const fechaDocumento=String(doc.fecha||'').slice(0,10);
 const [year,month,day]=fechaDocumento.split('-');
 const fechaLegible=day&&month&&year?`${day}/${month}/${year}`:date(doc.fecha);
 const numero=doc.numero||'SIN NUMERACIÓN';
 // Cada documento conserva su CAI y sus rangos guardados. El prefijo fiscal
 // se obtiene de la autorización vinculada, no del CAI que esté activo hoy.
 const autorizacion=autorizaciones.find(a=>a.id===doc.cai_id);
 const caiReferencia=isProforma?autorizaciones.find(a=>a.activa):null;
 const caiVista=isFactura?autorizacion:caiReferencia;
 const prefijoFiscal=caiVista
  ? [caiVista.establecimiento,caiVista.punto_emision,caiVista.tipo_documento].join('-')
  : /^\d{3}-\d{3}-\d{2}-\d{8}$/.test(numero)
   ? numero.split('-').slice(0,3).join('-')
   : '';
 const formatoRango=(n)=> n===null||n===undefined||n===''||!prefijoFiscal
  ? '—' : `${prefijoFiscal}-${String(n).padStart(8,'0')}`;
 const formatoFechaFiscal=(valor)=>{
  if(!valor)return '—';
  const partes=String(valor).slice(0,10).split('-');
  return partes.length===3?`${partes[2]}/${partes[1]}/${partes[0]}`:String(valor);
 };

 function print(){window.print()}
 function compartirWhatsApp(){
   const tipoDocumento=isFactura?'Factura original':isCotizacion?'Cotización comercial':'Proforma';
   const articulos=(doc.items||[]).map(item=>
     `• ${Number(item.cantidad).toLocaleString('es-HN')} × ${item.descripcion}: ${fmt(item.total)}`
   );
   const lineas=[
     `*${company.razon_social||company.nombre||'INNOVANET'}*`,
     `*${tipoDocumento}*`,
     `Número: ${numero}`,
     `Fecha: ${fechaLegible}`,
     `Cliente: ${doc.cliente_nombre||'Consumidor final'}`,
     ...(articulos.length?['', '*Detalle:*', ...articulos]:[]),
     '',
     `*Total a pagar: ${fmt(doc.total)}*`,
     `Valor en letras: ${totalEnLetras(doc.total,moneda)}`,
     ...(isFactura&&doc.cai_texto?[`CAI: ${doc.cai_texto}`]:[]),
     ...(doc.estado==='anulada'?['*DOCUMENTO ANULADO*']:[]),
     '',
     'Mensaje generado desde INNOVANET.'
   ];
   const enlace=`https://wa.me/?text=${encodeURIComponent(lineas.join('\n'))}`;
   const ventana=window.open(enlace,'_blank','noopener,noreferrer');
   if(!ventana){window.location.href=enlace;}
 }
 async function share(){
   const texto=`${labelTipo(doc.tipo)} ${numero} · ${doc.cliente_nombre} · ${fmt(doc.total)}`;
   if(navigator.share){try{await navigator.share({title:`INNOVANET ${numero}`,text:texto})}catch{}}
   else{try{await navigator.clipboard.writeText(texto);alert('Resumen copiado. Para compartir el PDF, utiliza Imprimir / PDF y guárdalo primero.')}catch{alert(texto)}}
 }
 return <div className="modal-backdrop preview-layer" onClick={onClose}>
  <div className="modal preview-modal" onClick={e=>e.stopPropagation()}>
   <div className="modal-title no-print"><div><b>Vista previa del documento</b><small>{numero}</small></div><div className="row gap"><button className="btn ghost" onClick={share}><Share2 size={17}/> Compartir</button><button type="button" className="btn ghost" title="Abrir WhatsApp con el resumen listo para enviar" onClick={compartirWhatsApp}><span aria-hidden="true" style={{fontSize:18,color:"#16a34a"}}>●</span> WhatsApp</button><button className="btn primary" onClick={print}><Printer size={17}/> Imprimir / PDF</button>{isCotizacion&&doc.estado==='borrador'&&!cotizacionVinculada&&<><button className="btn primary" onClick={()=>onConvertQuote('proforma')}>A proforma</button><button className="btn primary" onClick={()=>onConvertQuote('factura')}>A factura</button></>}{isProforma&&doc.estado==='borrador'&&!facturaVinculada&&<button className="btn primary" onClick={onConvert}><FileCheck2 size={17}/> Convertir a factura</button>}{!isFactura&&facturaVinculada&&<button className="btn ghost" onClick={()=>onOpenRelated(facturaVinculada)}><FileCheck2 size={17}/> Ver factura emitida</button>}{!isFactura&&doc.estado==='borrador'&&!facturaVinculada&&!cotizacionVinculada&&<button className="btn ghost" onClick={onEdit}><Edit3 size={17}/> Editar</button>}<button className="icon-button" onClick={onClose}><X size={22}/></button></div></div>
   <article className={'paper fiscal-paper '+(isProforma?'paper-proforma':isCotizacion?'paper-cotizacion':'paper-factura')} id="print-document">{!isFactura&&<div className="document-watermark">{isProforma?'PROFORMA':'COTIZACIÓN'}</div>}
    <header className="fiscal-banner">{isFactura?'FACTURA ORIGINAL':isProforma?'PROFORMA':'COTIZACIÓN'}</header>
    <h1 className="fiscal-company-name">{company.razon_social||company.nombre||'INNOVANET'}</h1>
    <div className="fiscal-top">
      <div className="fiscal-company-details">
        <img className="fiscal-logo" src={`${import.meta.env.BASE_URL}logo-innovanet.png`} alt="Logotipo INNOVANET"/>
        <p><b>Dirección:</b> {company.direccion||'Dirección no configurada'}</p>
        <p><b>E-mail:</b> {company.correo||'No configurado'}</p>
        <p><b>Tel.:</b> {company.telefono||'No configurado'}</p>
      </div>
      <div className="fiscal-identification">
        <div className="fiscal-date"><b>FECHA</b><span>{day||'—'}</span><span>{month||'—'}</span><span>{year||'—'}</span></div>
        <div className="fiscal-number">{numero}</div>
        {fiscal&&<><div className="fiscal-cai"><strong>CAI:</strong> {isFactura?doc.cai_texto||'SIN AUTORIZACIÓN REGISTRADA':caiReferencia?.cai || 'SIN AUTORIZACIÓN DE REFERENCIA'}</div><p className="fiscal-rtn"><b>R.T.N.</b> {company.rtn||'No configurado'}</p></>}
      </div>
    </div>
    <section className="fiscal-customer">
      <div className="fiscal-client-line"><b>NOMBRE:</b><span>{doc.cliente_nombre||'Consumidor final'}</span><b>RTN:</b><span>{doc.cliente_rtn||'—'}</span></div>
      <div className="fiscal-client-line fiscal-address"><b>DIRECCIÓN:</b><span>{doc.cliente_direccion||'—'}</span></div>
    </section>
    <table className="fiscal-table">
     <thead><tr><th>Cantidad</th><th>Descripción</th><th>Precio Unit.<small>{moneda}</small></th><th>Descuentos y rebajas</th><th>Total {moneda}</th></tr></thead>
     <tbody>{(doc.items||[]).map((it,i)=><tr key={it.id||i}><td>{Number(it.cantidad).toLocaleString('es-HN')}</td><td>{it.descripcion}</td><td>{fmt(it.precio)}</td><td>{Number(it.descuento||0)>0?fmt(it.descuento):'—'}</td><td>{fmt(it.total)}</td></tr>)}</tbody>
    </table>
    <div className="fiscal-bottom">
      <div className="fiscal-legal">
       <p><b>Valor en letras:</b> <i>{totalEnLetras(doc.total,moneda)}</i></p>
       {fiscal&&<><p><b>Fecha límite de emisión:</b> {isFactura?formatoFechaFiscal(doc.fecha_limite):caiReferencia?formatoFechaFiscal(caiReferencia.fecha_limite):'Sin autorización de referencia'}</p><p><b>Rango autorizado:</b> {isFactura?`${formatoRango(doc.rango_desde)} - ${formatoRango(doc.rango_hasta)}`:caiReferencia?`${formatoRango(caiReferencia.desde)} - ${formatoRango(caiReferencia.hasta)}`:'Sin autorización de referencia'}</p>
       <div className="fiscal-correlativos">{[['orden_compra_exenta','N° Correlativo de Orden de Compra Exenta:'],['constancia_registro_exonerado','N° Correlativo de Constancia de Registro Exonerado:'],['registro_sag','N° Identificativo del Registro de la SAG:']].map(([k,t])=><div key={k} className="fiscal-correlativo"><strong>{t}</strong><span title={doc[k]||''}>{doc[k]||'________________'}</span></div>)}</div>{isProforma&&<p className="fiscal-reference-warning">CAI y rango mostrados solo como referencia de posible facturación. Esta proforma no tiene autorización fiscal propia.</p>}</>}
       {doc.observaciones&&<p className="fiscal-observations"><b>Observaciones:</b> {doc.observaciones}</p>}
      </div>
      <table className="fiscal-totals"><tbody>
        <tr><th>Sub-total</th><td>{fmt(doc.subtotal)}</td></tr>
        {fiscal?<>
        <tr><th>Importe Exonerado</th><td>{fmt(doc.importe_exonerado)}</td></tr>
        <tr><th>Importe Exento</th><td>{fmt(doc.importe_exento)}</td></tr>
        <tr><th>Imp. Gravado 15% I.S.V. L</th><td>{fmt(doc.gravado_15)}</td></tr>
        <tr><th>Imp. Gravado 18% I.S.V. L</th><td>{fmt(doc.gravado_18)}</td></tr>
        <tr><th>15% I.S.V.</th><td>{fmt(doc.impuesto_15)}</td></tr>
        <tr><th>18% I.S.V.</th><td>{fmt(doc.impuesto_18)}</td></tr>
        </>:<><tr><th>Descuentos y rebajas</th><td>{fmt(doc.descuento)}</td></tr><tr><th>Impuestos</th><td>{fmt(doc.impuesto)}</td></tr></>}
        <tr className="fiscal-total"><th>Total a Pagar</th><td>{fmt(doc.total)}</td></tr>
      </tbody></table>
    </div>
    <footer className="fiscal-footer"><strong>{isCotizacion?'COTIZACIÓN COMERCIAL':company.pie_documento||'LA FACTURA ES BENEFICIO DE TODOS “EXÍJALA”'}</strong>{!isFactura&&<small>DOCUMENTO PRIVADO - NO VÁLIDO PARA EFECTOS FISCALES / NO SUSTITUYE A LA FACTURA ORIGINAL</small>}</footer>
    {doc.estado==='anulada'&&<div className="cancelled">ANULADA</div>}
   </article>
  </div>
 </div>
}

export default App;